import { createHash } from "node:crypto";
const hash = (value) => createHash("sha256").update(value).digest("hex");
const kinds = ["missing-value", "app-choice", "permission", "task-scope"];
const bindingSchema = {
  type: "object",
  additionalProperties: false,
  required: ["sourceId", "quote"],
  properties: {
    sourceId: { type: "string" },
    quote: { type: "string", minLength: 1, maxLength: 512 },
  },
};
const ordinaryPresentationSchema = {
  type: "object",
  additionalProperties: false,
  required: ["kind", "subject", "choices"],
  properties: {
    kind: { type: "string", enum: kinds },
    subject: bindingSchema,
    choices: { type: "array", maxItems: 8, items: bindingSchema },
  },
};
export const clarificationPresentationJsonSchema = {
  anyOf: [
    ordinaryPresentationSchema,
    {
      type: "object",
      additionalProperties: false,
      required: ["kind", "subject", "control", "choices"],
      properties: {
        kind: { type: "string", enum: ["read-only-path"] },
        subject: bindingSchema,
        control: bindingSchema,
        choices: { type: "array", maxItems: 0, items: bindingSchema },
      },
    },
  ],
};
const exact = (value, keys) =>
  value &&
  typeof value === "object" &&
  !Array.isArray(value) &&
  Object.keys(value).length === keys.length &&
  keys.every((key) => Object.hasOwn(value, key));
export function validateClarificationPresentation(value) {
  const viewingPath = value?.kind === "read-only-path";
  const binding = (v) =>
    exact(v, ["sourceId", "quote"]) &&
    typeof v.sourceId === "string" &&
    typeof v.quote === "string" &&
    v.quote.trim() &&
    v.quote.length <= 512;
  if (
    !exact(
      value,
      viewingPath
        ? ["kind", "subject", "control", "choices"]
        : ["kind", "subject", "choices"],
    ) ||
    !(viewingPath || kinds.includes(value.kind)) ||
    !binding(value.subject) ||
    (viewingPath && !binding(value.control)) ||
    !Array.isArray(value.choices) ||
    value.choices.length > 8 ||
    !value.choices.every(binding) ||
    (value.kind === "app-choice"
      ? value.choices.length < 2
      : value.choices.length !== 0)
  )
    throw Error("Clarification needs a supported source-bound question.");
  return value;
}
export function clarificationSourceId(kind, text, selector = "") {
  if (typeof text !== "string")
    throw Error("Clarification source is not text.");
  return `${kind}/${selector ? selector + "/" : ""}${hash(text)}`;
}
export function parseClarificationSourceId(id) {
  let match;
  if ((match = /^task\/([a-f0-9]{64})$/.exec(id)))
    return { kind: "task", sha256: match[1] };
  if ((match = /^parameter\/(0|[1-9][0-9]{0,3})\/([a-f0-9]{64})$/.exec(id)))
    return { kind: "parameter", index: Number(match[1]), sha256: match[2] };
  if (
    (match =
      /^application\/(screen-(?:initial|[0-9]+)\.ui\.json)\/(text|snapshot)\/([a-f0-9]{64})$/.exec(
        id,
      ))
  )
    return {
      kind: "application",
      path: match[1],
      field: match[2],
      sha256: match[3],
    };
  throw Error("Unsupported clarification source.");
}
/** Only caller task/parameter names and already acquired page content enter this
 * registry. Generated responses, logs and internal metadata never enter it. */
export function createClarificationSources(scenario, parameterNames = []) {
  const caller = new Map([
    [clarificationSourceId("task", scenario), { kind: "task", text: scenario }],
  ]);
  parameterNames.forEach((text, index) =>
    caller.set(clarificationSourceId("parameter", text, String(index)), {
      kind: "parameter",
      text,
    }),
  );
  let application = new Map();
  return {
    observe(path, page) {
      if (!/^screen-(?:initial|[0-9]+)\.ui\.json$/.test(path))
        throw Error("Unsupported clarification capture.");
      application = new Map(
        ["text", "snapshot"].flatMap((field) =>
          typeof page?.[field] !== "string"
            ? []
            : [
                [
                  clarificationSourceId(
                    "application",
                    page[field],
                    `${path}/${field}`,
                  ),
                  { kind: "application", text: page[field] },
                ],
              ],
        ),
      );
    },
    snapshot() {
      const sources = new Map([...caller, ...application]);
      return {
        // No page dumps. The model already has the task and acquired screen.
        descriptors: [...sources].map(([sourceId, source]) => ({
          sourceId,
          kind: source.kind,
        })),
        resolve: (sourceId) => sources.get(sourceId),
      };
    },
  };
}
/** Membership proves literal source content, not a field association, permission,
 * current state or completion. Templates preserve those limits explicitly. */
export async function renderClarificationPresentation(value, resolve) {
  const p = validateClarificationPresentation(value);
  const read = async (binding) => {
    const source = await resolve(binding.sourceId);
    const id = parseClarificationSourceId(binding.sourceId);
    if (
      !source ||
      source.kind !== id.kind ||
      hash(source.text) !== id.sha256 ||
      !source.text.includes(binding.quote)
    )
      throw Error("Clarification source binding is unavailable.");
    return { kind: source.kind, text: binding.quote };
  };
  const subject = await read(p.subject);
  const choices = await Promise.all(p.choices.map(read));
  const quote = (text) => JSON.stringify(text);
  const describe = (source) =>
    source.kind === "application"
      ? `the captured application text ${quote(source.text)}`
      : source.kind === "parameter"
        ? `the task parameter ${quote(source.text)}`
        : `the task excerpt ${quote(source.text)}`;
  let question;
  if (p.kind === "read-only-path") {
    const control = await read(p.control);
    if (subject.kind !== "task" || control.kind !== "application")
      throw Error(
        "Read-only paths need the original task and captured application control.",
      );
    question = `Is there a read-only way to check ${quote(subject.text)}? The page shows ${quote(control.text)}. Give a read-only viewing path, or say it is unavailable.`;
  } else if (p.kind === "app-choice") {
    if (
      subject.kind !== "application" ||
      choices.some((c) => c.kind !== "application") ||
      new Set(choices.map((c) => c.text)).size !== choices.length
    )
      throw Error(
        "Application choices need distinct captured application excerpts.",
      );
    question = `Which captured application value should be used for this task? Context: ${quote(subject.text)}. Choices: ${choices.map((c) => quote(c.text)).join("; ")}.`;
  } else if (p.kind === "permission") {
    if (subject.kind !== "task")
      throw Error(
        "Permission clarification must stay within the original task.",
      );
    question = `Is ${describe(subject)} allowed under the existing task restrictions? Your answer clarifies those restrictions; it does not grant new access or expand the task.`;
  } else if (p.kind === "task-scope") {
    if (subject.kind !== "task")
      throw Error("Task scope needs the original task.");
    question = `What intended behavior or limit applies to ${describe(subject)}? Keep the existing task restrictions.`;
  } else question = `What value should be used for ${describe(subject)}?`;
  // This is still a task-scope question to the caller. The richer native
  // presentation supplies its bound context without changing public kinds.
  return {
    kind: p.kind === "read-only-path" ? "task-scope" : p.kind,
    question,
  };
}
